var errReminderDelivery = errors.New("reminder delivery failed")

type reminderSender interface {
	Send(string, any) error
}

type reminderAppointment struct {
	store.Appointment
	StartsLocal string `json:"starts_local"`
}

// Include the records, not just today's exported template's placeholders:
// Relaywave templates are edited independently of this service.
type reminderVars struct {
	Patient     store.Patient       `json:"patient"`
	Appointment reminderAppointment `json:"appointment"`
	Clinician   store.Clinician     `json:"clinician"`
	Clinic      store.Clinic        `json:"clinic"`
}

type reminderMessage struct {
	To        string       `json:"to"`
	Template  string       `json:"template"`
	Reference string       `json:"reference"`
	Vars      reminderVars `json:"vars"`
}

type sentReminder struct {
	AppointmentID string    `json:"appointment_id"`
	StartsAt      time.Time `json:"starts_at"`
	SentAt        time.Time `json:"sent_at"`
}

type reminderKey struct {
	id    string
	start string
}

func reminderID(id string, start time.Time) reminderKey {
	// Compare instants, not the input's time-zone spelling, without losing
	// fractional seconds when a booking is moved.
	return reminderKey{id, start.UTC().Format(time.RFC3339Nano)}
}

func remind(s *store.Store, args []string, out io.Writer, client reminderSender) error {
	fs := flag.NewFlagSet("remind", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	nowText := fs.String("now", time.Now().Format(time.RFC3339Nano), "current time (RFC3339)")
	if err := fs.Parse(args); err != nil || fs.NArg() != 0 {
		return errUsage
	}
	now, err := time.Parse(time.RFC3339, *nowText)
	if err != nil {
		return errUsage
	}

	// Cron runs can overlap. Hold the lock across reading history, sending,
	// and saving it, rather than merely protecting the file replacement.
	lock, err := os.OpenFile(filepath.Join(s.Dir, "reminders_sent.lock"), os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return err
	}
	defer lock.Close()
	if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
		return err
	}
	defer syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)

	path := filepath.Join(s.Dir, "reminders_sent.json")
	history, err := loadReminderHistory(path)
	if err != nil {
		return err
	}
	sent := make(map[reminderKey]bool, len(history))
	for _, r := range history {
		sent[reminderID(r.AppointmentID, r.StartsAt)] = true
	}

	n := 0
	var deliveryErrors error
	for _, a := range schedule.Between(s, now, now.Add(24*time.Hour)) {
		p := s.Patients[a.PatientID]
		if !p.Contact.SMS || p.Phone == "" || sent[reminderID(a.ID, a.StartsAt)] {
			continue
		}
		clinic := s.Clinics[a.ClinicID]
		loc := clinic.Location()
		hour := now.In(loc).Hour()
		if hour < 8 || hour >= 21 {
			continue
		}
		message := reminderMessage{
			To: p.Phone, Template: clinic.SMSTemplate, Reference: "appt-" + a.ID,
			Vars: reminderVars{
				Patient: p, Clinic: clinic, Clinician: s.Clinicians[a.ClinicianID],
				Appointment: reminderAppointment{a, a.StartsAt.In(loc).Format("Mon 2 Jan, 15:04")},
			},
		}
		if err := client.Send("sms", message); err != nil {
			deliveryErrors = errors.Join(deliveryErrors, fmt.Errorf("appointment %s: %w", a.ID, err))
			continue
		}
		n++
		fmt.Fprintf(out, "reminded %s\n", a.ID)
		history = append(history, sentReminder{a.ID, a.StartsAt, now})
		// Save each success so a later failed send does not lose earlier work.
		if err := saveReminderHistory(path, history); err != nil {
			fmt.Fprintf(out, "sent %d\n", n)
			return errors.Join(deliveryResult(deliveryErrors), err)
		}
		sent[reminderID(a.ID, a.StartsAt)] = true
	}
	fmt.Fprintf(out, "sent %d\n", n)
	return deliveryResult(deliveryErrors)
}

func deliveryResult(err error) error {
	if err == nil {
		return nil
	}
	return errors.Join(errReminderDelivery, err)
}

func loadReminderHistory(path string) ([]sentReminder, error) {
	raw, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var history []sentReminder
	if err := json.Unmarshal(raw, &history); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	for _, r := range history {
		if r.AppointmentID == "" || r.StartsAt.IsZero() {
			return nil, fmt.Errorf("%s: invalid reminder record", path)
		}
	}
	return history, nil
}

func saveReminderHistory(path string, history []sentReminder) error {
	raw, err := json.MarshalIndent(history, "", "  ")
	if err != nil {
		return err
	}
	// A failed write must not truncate the previous successful-send history.
	f, err := os.CreateTemp(filepath.Dir(path), ".reminders-*")
	if err != nil {
		return err
	}
	defer os.Remove(f.Name())
	defer f.Close()
	if _, err := f.Write(append(raw, '\n')); err != nil {
		return err
	}
	if err := f.Sync(); err != nil {
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	return os.Rename(f.Name(), path)
}
