        a.ID, a.StartsAt, a.Status, a.PatientID = tc.id, now.Add(tc.delta), tc.status, tc.patient
        appointments = append(appointments, a)
    }
    writeReminderJSON(t, s.Dir, "appointments.json", appointments)
    runReminder(t, now.Format(time.RFC3339), 0, "reminded a-lower\nreminded b-upper\nsent 2\n")
    if len(readSMS(t, outbox)) != 2 { t.Fatal("unexpected deliveries") }
}

