func TestRemindConcurrentRunsDoNotDuplicate(t *testing.T) {
    s, _ := reminderFixture(t)
    var sends atomic.Int32
    sender := reminderSendFunc(func(_ string, _ any) error {
        sends.Add(1)
        return nil
    })
    type result struct { output string; err error }
    results := make(chan result, 4)
    start := make(chan struct{})
    for i := 0; i < 4; i++ {
        go func() {
            <-start
            var out bytes.Buffer
            err := remind(s, []string{"--now", "2026-11-16T16:00:00Z"}, &out, sender)
            results <- result{out.String(), err}
        }()
    }
    close(start)
    successfulRuns := 0
    for i := 0; i < 4; i++ {
        r := <-results
        if r.err != nil { t.Fatal(r.err) }
        switch r.output {
        case "sent 0\n":
        case "reminded ap-506\nreminded ap-501\nreminded ap-502\nreminded ap-507\nreminded ap-505\nsent 5\n":
            successfulRuns++
        default:
            t.Fatalf("unexpected output: %q", r.output)
        }
    }
    if sends.Load() != 5 || successfulRuns != 1 { t.Fatalf("%d sends from %d runs", sends.Load(), successfulRuns) }
